import{_ as t,a0 as l,w as d,s as o,I as n,x as a,a1 as p,A as i,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"樹莓派自建 NAS 雲盤之——樹莓派搭建網絡存儲盤 | LCTT x X-CMD","titleTemplate":false,"description":"樹莓派自建 NAS 雲盤之——樹莓派搭建網絡存儲盤 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"樹莓派自建 NAS 雲盤之——樹莓派搭建網絡存儲盤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"樹莓派自建 NAS 雲盤之——樹莓派搭建網絡存儲盤 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180724 Building a network attached storage device with a Raspberry Pi","title":"樹莓派自建 NAS 雲盤之——樹莓派搭建網絡存儲盤","tag":"201810","desc":""},"relativePath":"201810/20180724 Building a network attached storage device with a Raspberry Pi.md","filePath":"[post].md"}'),u={name:"201810/20180724 Building a network attached storage device with a Raspberry Pi.md"};function c(b,s,g,k,h,f){const e=l("Link");return d(),o("div",null,[s[31]||(s[31]=n("h1",{id:"樹莓派自建-nas-雲盤之——樹莓派搭建網絡存儲盤",tabindex:"-1"},[a("樹莓派自建 NAS 雲盤之——樹莓派搭建網絡存儲盤 "),n("a",{class:"header-anchor",href:"#樹莓派自建-nas-雲盤之——樹莓派搭建網絡存儲盤","aria-label":"Permalink to “樹莓派自建 NAS 雲盤之——樹莓派搭建網絡存儲盤”"},"​")],-1)),s[32]||(s[32]=n("blockquote",null,[n("p",null,"跟隨這些逐步指導構建你自己的基於樹莓派的 NAS 系統。")],-1)),s[33]||(s[33]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/bus-storage.png?itok=95-zvHYl",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("我將在接下來的這三篇文章中講述如何搭建一個簡便、實用的 NAS 雲盤系統。我在這個中心化的存儲系統中存儲數據，並且讓它每晚都會自動的備份增量數據。本系列文章將利用 NFS 文件系統將磁盤掛載到同一網絡下的不同設備上，使用 ",-1)),p(e,{href:"https://nextcloud.com/"},{default:i(()=>[...s[0]||(s[0]=[a("Nextcloud",-1)])]),_:1}),s[2]||(s[2]=a(" 來離線訪問數據、分享數據。",-1))]),s[34]||(s[34]=n("p",null,"本文主要講述將數據盤掛載到遠程設備上的軟硬件步驟。本系列第二篇文章將討論數據備份策略、如何添加定時備份數據任務。最後一篇文章中我們將會安裝 Nextcloud 軟件，用户通過 Nextcloud 提供的 web 界面可以方便的離線或在線訪問數據。本系列教程最終搭建的 NAS 雲盤支持多用户操作、文件共享等功能，所以你可以通過它方便的分享數據，比如説你可以發送一個加密鏈接，跟朋友分享你的照片等等。",-1)),s[35]||(s[35]=n("p",null,"最終的系統架構如下圖所示：",-1)),s[36]||(s[36]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/uploads/nas_part1.png",alt:""})],-1)),s[37]||(s[37]=n("h3",{id:"硬件",tabindex:"-1"},[a("硬件 "),n("a",{class:"header-anchor",href:"#硬件","aria-label":"Permalink to “硬件”"},"​")],-1)),s[38]||(s[38]=n("p",null,"首先需要準備硬件。本文所列方案只是其中一種示例，你也可以按不同的硬件方案進行採購。",-1)),n("p",null,[s[4]||(s[4]=a("最主要的就是",-1)),p(e,{href:"https://www.raspberrypi.org/products/raspberry-pi-3-model-b/"},{default:i(()=>[...s[3]||(s[3]=[a("樹莓派 3",-1)])]),_:1}),s[5]||(s[5]=a("，它帶有四核 CPU、1G RAM，以及（比較）快速的網絡接口。數據將存儲在兩個 USB 磁盤驅動器上（這裏使用 1TB 磁盤）；其中一個磁盤用於每天數據存儲，另一個用於數據備份。請務必使用有源 USB 磁盤驅動器或者帶附加電源的 USB 集線器，因為樹莓派無法為兩個 USB 磁盤驅動器供電。",-1))]),s[39]||(s[39]=n("h3",{id:"軟件",tabindex:"-1"},[a("軟件 "),n("a",{class:"header-anchor",href:"#軟件","aria-label":"Permalink to “軟件”"},"​")],-1)),n("p",null,[s[9]||(s[9]=a("在該社區中最活躍的操作系統當屬 ",-1)),p(e,{href:"https://www.raspbian.org/"},{default:i(()=>[...s[6]||(s[6]=[a("Raspbian",-1)])]),_:1}),s[10]||(s[10]=a("，便於定製個性化項目。已經有很多 ",-1)),p(e,{href:"https://www.raspberrypi.org/documentation/installation/installing-images/"},{default:i(()=>[...s[7]||(s[7]=[a("操作指南",-1)])]),_:1}),s[11]||(s[11]=a(" 講述如何在樹莓派中安裝 Raspbian 系統，所以這裏不再贅述。在撰寫本文時，最新的官方支持版本是 ",-1)),p(e,{href:"https://www.raspberrypi.org/blog/raspbian-stretch/"},{default:i(()=>[...s[8]||(s[8]=[a("Raspbian Stretch",-1)])]),_:1}),s[12]||(s[12]=a("，它對我來説很好使用。",-1))]),s[40]||(s[40]=r(`<p>到此，我將假設你已經配置好了基本的 Raspbian 系統並且可以通過 <code>ssh</code> 訪問到你的樹莓派。</p><h3 id="準備-usb-磁盤驅動器" tabindex="-1">準備 USB 磁盤驅動器 <a class="header-anchor" href="#準備-usb-磁盤驅動器" aria-label="Permalink to “準備 USB 磁盤驅動器”">​</a></h3><p>為了更好地讀寫數據，我建議使用 ext4 文件系統去格式化磁盤。首先，你必須先找到連接到樹莓派的磁盤。你可以在 <code>/dev/sd/&lt;x&gt;</code> 中找到磁盤設備。使用命令 <code>fdisk -l</code>，你可以找到剛剛連接的兩塊 USB 磁盤驅動器。請注意，操作下面的步驟將會清除 USB 磁盤驅動器上的所有數據，請做好備份。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pi@raspberrypi:~ $ sudo fdisk -l</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;...&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Disk /dev/sda: 931.5 GiB, 1000204886016 bytes, 1953525168 sectors</span></span>
<span class="line"><span>Units: sectors of 1 * 512 = 512 bytes</span></span>
<span class="line"><span>Sector size (logical/physical): 512 bytes / 512 bytes</span></span>
<span class="line"><span>I/O size (minimum/optimal): 512 bytes / 512 bytes</span></span>
<span class="line"><span>Disklabel type: dos</span></span>
<span class="line"><span>Disk identifier: 0xe8900690</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Device     Boot Start        End    Sectors   Size Id Type</span></span>
<span class="line"><span>/dev/sda1        2048 1953525167 1953523120 931.5G 83 Linux</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>Disk /dev/sdb: 931.5 GiB, 1000204886016 bytes, 1953525168 sectors</span></span>
<span class="line"><span>Units: sectors of 1 * 512 = 512 bytes</span></span>
<span class="line"><span>Sector size (logical/physical): 512 bytes / 512 bytes</span></span>
<span class="line"><span>I/O size (minimum/optimal): 512 bytes / 512 bytes</span></span>
<span class="line"><span>Disklabel type: dos</span></span>
<span class="line"><span>Disk identifier: 0x6aa4f598</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Device     Boot Start        End    Sectors   Size Id Type</span></span>
<span class="line"><span>/dev/sdb1  *     2048 1953521663 1953519616 931.5G  83 Linux</span></span></code></pre></div><p>由於這些設備是連接到樹莓派的唯一的 1TB 的磁盤，所以我們可以很容易的辨別出 <code>/dev/sda</code> 和 <code>/dev/sdb</code> 就是那兩個 USB 磁盤驅動器。每個磁盤末尾的分區表提示了在執行以下的步驟後如何查看，這些步驟將會格式化磁盤並創建分區表。為每個 USB 磁盤驅動器按以下步驟進行操作（假設你的磁盤也是 <code>/dev/sda</code> 和 <code>/dev/sdb</code>，第二次操作你只要替換命令中的 <code>sda</code> 為 <code>sdb</code> 即可）。</p><p>首先，刪除磁盤分區表，創建一個新的並且只包含一個分區的新分區表。在 <code>fdisk</code> 中，你可以使用交互單字母命令來告訴程序你想要執行的操作。只需要在提示符 <code>Command(m for help):</code> 後輸入相應的字母即可（可以使用 <code>m</code> 命令獲得更多詳細信息）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pi@raspberrypi:~ $ sudo fdisk /dev/sda</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Welcome to fdisk (util-linux 2.29.2).</span></span>
<span class="line"><span>Changes will remain in memory only, until you decide to write them.</span></span>
<span class="line"><span>Be careful before using the write command.</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>Command (m for help): o</span></span>
<span class="line"><span>Created a new DOS disklabel with disk identifier 0x9c310964.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Command (m for help): n</span></span>
<span class="line"><span>Partition type</span></span>
<span class="line"><span>   p   primary (0 primary, 0 extended, 4 free)</span></span>
<span class="line"><span>   e   extended (container for logical partitions)</span></span>
<span class="line"><span>Select (default p): p</span></span>
<span class="line"><span>Partition number (1-4, default 1):</span></span>
<span class="line"><span>First sector (2048-1953525167, default 2048):</span></span>
<span class="line"><span>Last sector, +sectors or +size{K,M,G,T,P} (2048-1953525167, default 1953525167):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Created a new partition 1 of type &#39;Linux&#39; and of size 931.5 GiB.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Command (m for help): p</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Disk /dev/sda: 931.5 GiB, 1000204886016 bytes, 1953525168 sectors</span></span>
<span class="line"><span>Units: sectors of 1 * 512 = 512 bytes</span></span>
<span class="line"><span>Sector size (logical/physical): 512 bytes / 512 bytes</span></span>
<span class="line"><span>I/O size (minimum/optimal): 512 bytes / 512 bytes</span></span>
<span class="line"><span>Disklabel type: dos</span></span>
<span class="line"><span>Disk identifier: 0x9c310964</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Device     Boot Start        End    Sectors   Size Id Type</span></span>
<span class="line"><span>/dev/sda1        2048 1953525167 1953523120 931.5G 83 Linux</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Command (m for help): w</span></span>
<span class="line"><span>The partition table has been altered.</span></span>
<span class="line"><span>Syncing disks.</span></span></code></pre></div><p>現在，我們將用 ext4 文件系統格式化新創建的分區 <code>/dev/sda1</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pi@raspberrypi:~ $ sudo mkfs.ext4 /dev/sda1</span></span>
<span class="line"><span>mke2fs 1.43.4 (31-Jan-2017)</span></span>
<span class="line"><span>Discarding device blocks: done</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;...&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Allocating group tables: done</span></span>
<span class="line"><span>Writing inode tables: done</span></span>
<span class="line"><span>Creating journal (1024 blocks): done</span></span>
<span class="line"><span>Writing superblocks and filesystem accounting information: done</span></span></code></pre></div><p>重複以上步驟後，讓我們根據用途來對它們建立標籤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pi@raspberrypi:~ $ sudo e2label /dev/sda1 data</span></span>
<span class="line"><span>pi@raspberrypi:~ $ sudo e2label /dev/sdb1 backup</span></span></code></pre></div><p>現在，讓我們安裝這些磁盤並存儲一些數據。以我運營該系統超過一年的經驗來看，當樹莓派啓動時（例如在斷電後），USB 磁盤驅動器並不是總被掛載，因此我建議使用 autofs 在需要的時候進行掛載。</p><p>首先，安裝 autofs 並創建掛載點：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pi@raspberrypi:~ $ sudo apt install autofs</span></span>
<span class="line"><span>pi@raspberrypi:~ $ sudo mkdir /nas</span></span></code></pre></div><p>然後添加下面這行來掛載設備 <code>/etc/auto.master</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/nas    /etc/auto.usb</span></span></code></pre></div><p>如果不存在以下內容，則創建 <code>/etc/auto.usb</code>，然後重新啓動 autofs 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>data -fstype=ext4,rw :/dev/disk/by-label/data</span></span>
<span class="line"><span>backup -fstype=ext4,rw :/dev/disk/by-label/backup</span></span>
<span class="line"><span>pi@raspberrypi3:~ $ sudo service autofs restart</span></span></code></pre></div><p>現在你應該可以分別訪問 <code>/nas/data</code> 以及 <code>/nas/backup</code> 磁盤了。顯然，到此還不會令人太興奮，因為你只是擦除了磁盤中的數據。不過，你可以執行以下命令來確認設備是否已經掛載成功：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pi@raspberrypi3:~ $ cd /nas/data</span></span>
<span class="line"><span>pi@raspberrypi3:/nas/data $ cd /nas/backup</span></span>
<span class="line"><span>pi@raspberrypi3:/nas/backup $ mount</span></span>
<span class="line"><span>&lt;...&gt;</span></span>
<span class="line"><span>/etc/auto.usb on /nas type autofs (rw,relatime,fd=6,pgrp=463,timeout=300,minproto=5,maxproto=5,indirect)</span></span>
<span class="line"><span>&lt;...&gt;</span></span>
<span class="line"><span>/dev/sda1 on /nas/data type ext4 (rw,relatime,data=ordered)</span></span>
<span class="line"><span>/dev/sdb1 on /nas/backup type ext4 (rw,relatime,data=ordered)</span></span></code></pre></div><p>首先進入對應目錄以確保 autofs 能夠掛載設備。autofs 會跟蹤文件系統的訪問記錄，並隨時掛載所需要的設備。然後 <code>mount</code> 命令會顯示這兩個 USB 磁盤驅動器已經掛載到我們想要的位置了。</p><p>設置 autofs 的過程容易出錯，如果第一次嘗試失敗，請不要沮喪。你可以上網搜索有關教程。</p><h3 id="掛載網絡存儲" tabindex="-1">掛載網絡存儲 <a class="header-anchor" href="#掛載網絡存儲" aria-label="Permalink to “掛載網絡存儲”">​</a></h3><p>現在你已經設置了基本的網絡存儲，我們希望將它安裝到遠程 Linux 機器上。這裏使用 NFS 文件系統，首先在樹莓派上安裝 NFS 服務器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pi@raspberrypi:~ $ sudo apt install nfs-kernel-server</span></span></code></pre></div><p>然後，需要告訴 NFS 服務器公開 <code>/nas/data</code> 目錄，這是從樹莓派外部可以訪問的唯一設備（另一個用於備份）。編輯 <code>/etc/exports</code> 添加如下內容以允許所有可以訪問 NAS 雲盤的設備掛載存儲：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/nas/data *(rw,sync,no_subtree_check)</span></span></code></pre></div><p>更多有關限制掛載到單個設備的詳細信息，請參閲 <code>man exports</code>。經過上面的配置，任何人都可以訪問數據，只要他們可以訪問 NFS 所需的端口：<code>111</code> 和 <code>2049</code>。我通過上面的配置，只允許通過路由器防火牆訪問到我的家庭網絡的 22 和 443 端口。這樣，只有在家庭網絡中的設備才能訪問 NFS 服務器。</p><p>如果要在 Linux 計算機掛載存儲，運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>you@desktop:~ $ sudo mkdir /nas/data</span></span>
<span class="line"><span>you@desktop:~ $ sudo mount -t nfs &lt;raspberry-pi-hostname-or-ip&gt;:/nas/data /nas/data</span></span></code></pre></div>`,30)),n("p",null,[s[14]||(s[14]=a("同樣，我建議使用 autofs 來掛載該網絡設備。如果需要其他幫助，請參看 ",-1)),p(e,{href:"https://opensource.com/article/18/6/using-autofs-mount-nfs-shares"},{default:i(()=>[...s[13]||(s[13]=[a("如何使用 Autofs 來掛載 NFS 共享",-1)])]),_:1}),s[15]||(s[15]=a("。",-1))]),s[41]||(s[41]=n("p",null,[a("現在你可以在遠程設備上通過 NFS 系統訪問位於你樹莓派 NAS 雲盤上的數據了。在後面一篇文章中，我將介紹如何使用 "),n("code",null,"rsync"),a(" 自動將數據備份到第二個 USB 磁盤驅動器。你將會學到如何使用 "),n("code",null,"rsync"),a(" 創建增量備份，在進行日常備份的同時還能節省設備空間。")],-1)),s[42]||(s[42]=n("hr",null,null,-1)),n("p",null,[s[17]||(s[17]=a("via: ",-1)),p(e,{href:"https://opensource.com/article/18/7/network-attached-storage-Raspberry-Pi"},{default:i(()=>[...s[16]||(s[16]=[a("https://opensource.com/article/18/7/network-attached-storage-Raspberry-Pi",-1)])]),_:1})]),n("p",null,[s[22]||(s[22]=a("作者：",-1)),p(e,{href:"https://opensource.com/users/ntlx"},{default:i(()=>[...s[18]||(s[18]=[a("Manuel Dewald",-1)])]),_:1}),s[23]||(s[23]=a(" 選題：",-1)),p(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[19]||(s[19]=[a("lujun9972",-1)])]),_:1}),s[24]||(s[24]=a(" 譯者：",-1)),p(e,{href:"https://github.com/jrglinux"},{default:i(()=>[...s[20]||(s[20]=[a("jrg",-1)])]),_:1}),s[25]||(s[25]=a(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[21]||(s[21]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[28]||(s[28]=a("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[26]||(s[26]=[a("LCTT",-1)])]),_:1}),s[29]||(s[29]=a(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...s[27]||(s[27]=[a("Linux中國",-1)])]),_:1}),s[30]||(s[30]=a(" 榮譽推出",-1))])])}const v=t(u,[["render",c]]);export{x as __pageData,v as default};
